import numpy as np, wave, subprocess, sys
sr=48000; TEMPO=float(sys.argv[1]) if len(sys.argv)>1 else 1.08
subprocess.run(['ffmpeg','-loglevel','error','-y','-i','fs/raw48.wav','-af',f'highpass=f=70,acompressor=threshold=-20dB:ratio=2.5:attack=5:release=90:makeup=2dB,atempo={TEMPO}','-ar','48000','-ac','1','fs/proc48.wav'],check=True)
w=wave.open('fs/proc48.wav'); x=np.frombuffer(w.readframes(w.getnframes()),np.int16).astype(float)/32768
R=[(0.24,2.68),(4.1,4.8),(5.58,6.3),(7.07,7.87),(8.94,12.48),(13.09,14.92),(15.83,19.68),(20.73,21.85),(22.74,23.67),(24.46,26.95),(27.75,29.06),(29.72,31.16),(32.11,33.88),(34.75,36.91),(37.94,38.52),(39.11,39.56),(40.07,40.53),(41.34,41.88),(42.66,43.68),(44.61,45.05),(46.05,48.16),(49.01,50.25),(51.05,52.25),(53.14,55.01),(55.84,57.31),(58.25,60.4),(60.86,62.6),(63.31,63.44),(63.61,65.02),(66.02,66.45),(66.66,68.27),(69.21,71.73),(72.5,74.98),(75.59,76.52),(77.47,77.85),(78.53,78.97),(80.03,81.0),(82.15,83.83),(84.9,87.12),(87.8,88.44),(89.37,90.86),(91.64,92.79),(93.76,94.76),(95.45,96.26),(97.31,98.99),(99.9,100.53),(101.55,102.41),(103.37,105.53),(106.26,108.07),(108.91,110.15),(110.86,111.61),(112.34,113.87),(114.11,115.36),(116.07,117.78),(118.44,120.88)]
runs=[(a/TEMPO,b/TEMPO) for a,b in R]
G=[([0],0.2),([1],3.1),([2],4.2),([3],5.4),([4],6.7),([5],9.5),([6],11.7),([7],15.7),([8],17.5),([9],18.3),([10],21.9),([11],23.6),([12],25.4),([13],27.3),([14],29.9),([15],30.5),([16],31.2),([17],32.2),([18],32.9),([19],34.5),([20],35.5),([21],38.6),([22],39.75),([23],42.1),([24],44.1),([25],46.0),([26],47.9),([27,28],49.75),([29,30],51.8),([31],54.6),([32],57.5),([33],59.85),([34],61.1),([35],61.9),([36],63.3),([37],64.5),([38],66.7),([39],68.45),([40],69.9),([41],71.4),([42,43],73.0),([44],75.7),([45],78.1),([46],79.6),([47],81.3),([48],83.55),([49],85.25),([50],86.3),([51],88.2),([52],89.95),([53],91.6),([54],93.9)]
assert sorted(i for g,_ in G for i in g)==list(range(len(runs)))
N=int(97.0*sr); out=np.zeros(N); prev_end=-1; drift=[]
for idx,target in G:
    s=runs[idx[0]][0]; e=runs[idx[-1]][1]
    at=max(target, prev_end+0.12)
    drift.append((target, round(at-target,2)))
    s0=s-0.05; e0=e+0.1
    pr=[r for r in runs if r[1]<=s]; nx=[r for r in runs if r[0]>=e]
    if pr: s0=max(s0,(pr[-1][1]+s)/2)
    if nx: e0=min(e0,(e+nx[0][0])/2)
    seg=x[int(s0*sr):int(e0*sr)].copy(); f=int(0.01*sr); seg[:f]*=np.linspace(0,1,f); seg[-f:]*=np.linspace(1,0,f)
    i=int((at-(s-s0))*sr); out[i:i+len(seg)]+=seg[:max(0,N-i)]
    prev_end=at+(e-s)
print('late by >0.25s:',[d for d in drift if d[1]>0.25]); print('ends',round(prev_end,2))
w=wave.open('fs/voice48.wav','wb'); w.setnchannels(1); w.setsampwidth(2); w.setframerate(sr); w.writeframes((np.clip(out,-1,1)*32767).astype(np.int16).tobytes()); w.close()
